// Simple endless‑space ship game
// Canvas id="game" – assumes full‑size canvas in HTML

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  // Resize to fill parent
  const resize = () => {
    canvas.width = canvas.clientWidth;
    canvas.height = canvas.clientHeight;
  };
  window.addEventListener('resize', resize);
  resize();

  // Ship state
  const ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    angle: 0, // radians
    vx: 0,
    vy: 0,
    radius: 10,
  };

  const keys = { left: false, right: false, up: false };
  document.addEventListener('keydown', e => {
    if (e.code === 'ArrowLeft') keys.left = true;
    if (e.code === 'ArrowRight') keys.right = true;
    if (e.code === 'ArrowUp') keys.up = true;
  });
  document.addEventListener('keyup', e => {
    if (e.code === 'ArrowLeft') keys.left = false;
    if (e.code === 'ArrowRight') keys.right = false;
    if (e.code === 'ArrowUp') keys.up = false;
  });

  const obstacles = [];
  const fuels = [];
  let obstacleTimer = 0;
  let fuelTimer = 0;
  let score = 0;
  let gameOver = false;

  const spawnObstacle = () => {
    const side = Math.random() < 0.5 ? 'top' : 'left';
    const radius = 15 + Math.random() * 20;
    const obj = {
      x: side === 'top' ? Math.random() * canvas.width : -radius,
      y: side === 'top' ? -radius : Math.random() * canvas.height,
      vx: 1 + Math.random() * 1.5,
      vy: 1 + Math.random() * 1.5,
      radius,
    };
    // move towards bottom‑right (ship forward direction)
    obj.vx *= Math.cos(ship.angle);
    obj.vy *= Math.sin(ship.angle);
    obstacles.push(obj);
  };

  const spawnFuel = () => {
    const obj = {
      x: Math.random() * canvas.width,
      y: -20,
      vx: 0,
      vy: 1.5,
      radius: 8,
    };
    fuels.push(obj);
  };

  const update = dt => {
    if (gameOver) return;
    // ship controls
    if (keys.left) ship.angle -= 0.04;
    if (keys.right) ship.angle += 0.04;
    if (keys.up) {
      ship.vx += Math.cos(ship.angle) * 0.1;
      ship.vy += Math.sin(ship.angle) * 0.1;
    }
    // drag
    ship.vx *= 0.99;
    ship.vy *= 0.99;
    ship.x += ship.vx;
    ship.y += ship.vy;
    // wrap around edges
    if (ship.x < 0) ship.x += canvas.width;
    if (ship.x > canvas.width) ship.x -= canvas.width;
    if (ship.y < 0) ship.y += canvas.height;
    if (ship.y > canvas.height) ship.y -= canvas.height;

    // spawn obstacles/fuel
    obstacleTimer += dt;
    fuelTimer += dt;
    if (obstacleTimer > 1500) { spawnObstacle(); obstacleTimer = 0; }
    if (fuelTimer > 3000) { spawnFuel(); fuelTimer = 0; }

    // move obstacles
    obstacles.forEach(o => { o.x += o.vx; o.y += o.vy; });
    fuels.forEach(f => { f.x += f.vx; f.y += f.vy; });
    // remove off‑screen
    const off = arr => arr.filter(o => o.x < canvas.width && o.y < canvas.height && o.x > -50 && o.y > -50);
    obstacles.splice(0, obstacles.length, ...off(obstacles));
    fuels.splice(0, fuels.length, ...off(fuels));

    // collisions
    for (const o of obstacles) {
      const dx = o.x - ship.x, dy = o.y - ship.y;
      if (Math.hypot(dx, dy) < o.radius + ship.radius) { gameOver = true; }
    }
    for (let i = fuels.length - 1; i >= 0; i--) {
      const f = fuels[i];
      if (Math.hypot(f.x - ship.x, f.y - ship.y) < f.radius + ship.radius) {
        score += 10;
        fuels.splice(i, 1);
      }
    }
    score += dt * 0.01; // survival score
  };

  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(15, 0);
    ctx.lineTo(-10, -7);
    ctx.lineTo(-10, 7);
    ctx.closePath();
    ctx.fillStyle = '#0ff';
    ctx.fill();
    ctx.restore();
    // obstacles
    ctx.fillStyle = '#f44';
    obstacles.forEach(o => {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.radius, 0, Math.PI * 2);
      ctx.fill();
    });
    // fuel cells
    ctx.fillStyle = '#ff0';
    fuels.forEach(f => {
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.radius, 0, Math.PI * 2);
      ctx.fill();
    });
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#f44';
      ctx.textAlign = 'center';
      ctx.font = '32px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  };

  let last = performance.now();
  const loop = now => {
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})();
